{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "The EC2 instances do not have `ebs_block_device` configurations with `encrypted = true`, meaning root volumes and any attached EBS volumes are unencrypted at rest."
    },
    {
      "check_id": "CKV_AWS_79",
      "title": "Ensure Instance Metadata Service Version 1 is not enabled",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "The `metadata_options` block is missing, which defaults to allowing IMDSv1. This exposes the instance to SSRF attacks that can retrieve temporary credentials from the metadata service."
    },
    {
      "check_id": "CKV_AWS_88",
      "title": "EC2 instance should not have public IP.",
      "resource": "aws_instance.ubuntu",
      "severity": "MEDIUM",
      "explanation": "The conditional logic `associate_public_ip_address = ( count.index == 1 ? true : false)` explicitly assigns a public IP address to one of the instances, increasing its attack surface unnecessarily if it resides in a private subnet."
    }
  ],
  "patched_code": "resource \"aws_instance\" \"ubuntu\" {\n  count         = 3\n  ami           = data.aws_ami.ubuntu_14_04.image_id\n  instance_type = \"t2.micro\"\n  \n  # Remediation CKV_AWS_88: Disable public IP assignment for security best practices.\n  # If a public IP is strictly required for specific use cases, ensure it is behind a WAF/Security Group restrictions.\n  associate_public_ip_address = false\n  \n  subnet_id = aws_subnet.my_subnet.id\n\n  # Remediation CKV_AWS_79: Enforce IMDSv2 by requiring tokens and setting hop limit to 1\n  metadata_options {\n    http_endpoint               = \"enabled\"\n    http_tokens                 = \"required\"\n    http_put_response_hop_limit = 1\n  }\n\n  # Remediation CKV_AWS_8: Enable encryption for the root volume\n  root_block_device {\n    encrypted = true\n  }\n}",
  "fix_summary": "Disabled public IP association to reduce exposure, enforced IMDSv2 via metadata_options to prevent credential theft, and enabled encryption on the root block device to protect data at rest."
}
